/* @autogenerated */
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { ConfirmDialogService } from '@shared/toolkit/dialog/confirm-dialog.service';
import { NotifyService } from '@shared/toolkit/notify/notify.service';
import { IdentityErrorReason, IdentityUiPort } from './identity-provider.interface';

/** Implementación por defecto de `IDENTITY_UI`: diálogo y snackbar traducidos. */
@Injectable({ providedIn: 'root' })
export class IdentityUiService implements IdentityUiPort {
  private readonly confirm = inject(ConfirmDialogService);
  private readonly notify = inject(NotifyService);

  confirmResetCredentials(reason: IdentityErrorReason): Observable<boolean> {
    return this.confirm.confirm({
      titleKey: 'identity.errors.title',
      messageKey: 'identity.errors.' + reason,
      okKey: 'identity.errors.reset',
    });
  }

  notifyError(reason: IdentityErrorReason): void {
    this.notify.error('identity.errors.' + reason);
  }
}
